WHEN OLD.priority IS NOT NEW.priority
BEGIN
  INSERT INTO events (kind, actor, target_kind, target_id, payload)
  VALUES ('idea.priority', (SELECT actor FROM temp.session_actor), 'idea', NEW.id, json_object('old', OLD.priority, 'new', NEW.priority));
END;
