-- Tombstones: the key columns of a deleted row, so the feed can still say what was there. A cascade (DELETE FROM
-- projects) fires them for every child row that it deletes.
CREATE TEMP TRIGGER ideas_deleted_event AFTER DELETE ON ideas
BEGIN
  INSERT INTO events (kind, actor, target_kind, target_id, payload)
  VALUES ('idea.deleted', (SELECT actor FROM temp.session_actor), 'idea', OLD.id, json_object('title', OLD.title, 'status', OLD.status, 'hypothesis', OLD.hypothesis));
END;
CREATE TEMP TRIGGER comments_deleted_event AFTER DELETE ON comments
BEGIN
  INSERT INTO events (kind, actor, target_kind, target_id, payload)
  VALUES ('comment.deleted', (SELECT actor FROM temp.session_actor), 'comment', OLD.id, json_object('target_kind', OLD.target_kind, 'target_id', OLD.target_id, 'author', OLD.author, 'kind', OLD.kind, 'body', OLD.body));
END;
CREATE TEMP TRIGGER candidates_deleted_event AFTER DELETE ON candidates
BEGIN
